    String[] queries = new String[] { "SELECT sum(2.5),organization_id FROM atable GROUP BY organization_id,entity_id", "SELECT avg(a_integer) FROM atable GROUP BY organization_id,substr(entity_id,1,3),entity_id", "SELECT count(a_string) FROM atable GROUP BY substr(organization_id,1),entity_id", "SELECT min('foo') FROM atable GROUP BY entity_id,organization_id", "SELECT min('foo'),sum(a_integer),avg(2.5),4.5,max(b_string) FROM atable GROUP BY substr(organization_id,1),entity_id", "SELECT sum(2.5) FROM atable", "SELECT avg(a_integer) FROM atable", "SELECT count(a_string) FROM atable", "SELECT min('foo') FROM atable LIMIT 5", "SELECT min('foo'),sum(a_integer),avg(2.5),4.5,max(b_string) FROM atable" };
    List<Object> binds = Collections.emptyList();
    String query = null;
    try {
        for (int i = 0; i < queries.length; i++) {
            query = queries[i];
            Scan scan = compileQuery(query, binds);
            ServerAggregators aggregators = ServerAggregators.deserialize(scan.getAttribute(BaseScannerRegionObserver.AGGREGATORS), null, null);
            Aggregator aggregator = aggregators.getAggregators()[0];
            assertTrue(aggregator instanceof CountAggregator);
        }
    } catch (Exception e) {
        throw new Exception(query, e);
    }
}

@Test
public void testInvalidArithmetic() throws Exception {
    String[] queries = new String[] { "SELECT entity_id,organization_id FROM atable where A_STRING - 5.5 < 0", "SELECT entity_id,organization_id FROM atable where A_DATE - 'transaction' < 0", "SELECT entity_id,organization_id FROM atable where A_DATE * 45 < 0", "SELECT entity_id,organization_id FROM atable where A_DATE / 45 < 0", "SELECT entity_id,organization_id FROM atable where 45 - A_DATE < 0", // RHS must be number
    "SELECT entity_id,organization_id FROM atable where A_DATE - to_date('2000-01-01 12:00:00') < to_date('2000-02-01 12:00:00')", // RHS must be number
    "SELECT entity_id,organization_id FROM atable where A_DATE - A_DATE + 1 < A_DATE", // RHS must be date
    "SELECT entity_id,organization_id FROM atable where A_DATE + 2 < 0", "SELECT entity_id,organization_id FROM atable where 45.5 - A_DATE < 0", "SELECT entity_id,organization_id FROM atable where 1 + A_DATE + A_DATE < A_DATE", "SELECT entity_id,organization_id FROM atable where A_STRING - 45 < 0", "SELECT entity_id,organization_id FROM atable where A_STRING / 45 < 0", "SELECT entity_id,organization_id FROM atable where A_STRING * 45 < 0", "SELECT entity_id,organization_id FROM atable where A_STRING + 45 < 0", "SELECT entity_id,organization_id FROM atable where A_STRING - 45 < 0", "SELECT entity_id,organization_id FROM atable where A_STRING - 'transaction' < 0" };
    Properties props = PropertiesUtil.deepCopy(TEST_PROPERTIES);
    Connection conn = DriverManager.getConnection(getUrl(), props);
    for (String query : queries) {
        try {
            PreparedStatement statement = conn.prepareStatement(query);
            statement.executeQuery();
            fail(query);
        } catch (SQLException e) {
            if (e.getMessage().contains("ERROR 203 (22005): Type mismatch.")) {
                continue;
            }
            throw new IllegalStateException("Didn't find type mismatch: " + query, e);
        }
    }
}

