        conn.createStatement().execute("CREATE TABLE t2(k TINYINT PRIMARY KEY," + " col1 CHAR(20), col2 CHAR(30), col3 double)");
        QueryPlan plan = getQueryPlan("SELECT * from t1 union all select * from t2", Collections.emptyList());
        RowProjector rowProj = plan.getProjector();
        assertTrue(rowProj.getColumnProjector(0).getExpression().getDataType() instanceof PInteger);
        assertTrue(rowProj.getColumnProjector(1).getExpression().getDataType() instanceof PChar);
        assertTrue(rowProj.getColumnProjector(1).getExpression().getMaxLength() == 20);
        assertTrue(rowProj.getColumnProjector(2).getExpression().getDataType() instanceof PVarchar);
        assertTrue(rowProj.getColumnProjector(2).getExpression().getMaxLength() == 30);
        assertTrue(rowProj.getColumnProjector(3).getExpression().getDataType() instanceof PDecimal);
        assertTrue(rowProj.getColumnProjector(3).getExpression().getScale() == 2);
    } finally {
        conn.close();
    }
}

@Test
public void testFuncIndexUsage() throws SQLException {
    Connection conn = DriverManager.getConnection(getUrl());
    try {
        conn.createStatement().execute("CREATE TABLE t1(k INTEGER PRIMARY KEY," + " col1 VARCHAR, col2 VARCHAR)");
        conn.createStatement().execute("CREATE TABLE t2(k INTEGER PRIMARY KEY," + " col1 VARCHAR, col2 VARCHAR)");
        conn.createStatement().execute("CREATE TABLE t3(j INTEGER PRIMARY KEY," + " col3 VARCHAR, col4 VARCHAR)");
        conn.createStatement().execute("CREATE INDEX idx ON t1 (col1 || col2)");
        String query = "SELECT a.k from t1 a where a.col1 || a.col2 = 'foobar'";
        ResultSet rs = conn.createStatement().executeQuery("EXPLAIN " + query);
        String explainPlan = QueryUtil.getExplainPlan(rs);
        assertEquals("CLIENT PARALLEL 1-WAY RANGE SCAN OVER IDX ['foobar']\n" + "    SERVER FILTER BY FIRST KEY ONLY", explainPlan);
        query = "SELECT k,j from t3 b join t1 a ON k = j where a.col1 || a.col2 = 'foobar'";
        rs = conn.createStatement().executeQuery("EXPLAIN " + query);
        explainPlan = QueryUtil.getExplainPlan(rs);
        assertEquals("CLIENT PARALLEL 1-WAY FULL SCAN OVER T3\n" + "    SERVER FILTER BY FIRST KEY ONLY\n" + "    PARALLEL INNER-JOIN TABLE 0\n" + "        CLIENT PARALLEL 1-WAY RANGE SCAN OVER IDX ['foobar']\n" + "            SERVER FILTER BY FIRST KEY ONLY\n" + "    DYNAMIC SERVER FILTER BY B.J IN (\"A.:K\")", explainPlan);
        query = "SELECT a.k,b.k from t2 b join t1 a ON a.k = b.k where a.col1 || a.col2 = 'foobar'";
        rs = conn.createStatement().executeQuery("EXPLAIN " + query);
        explainPlan = QueryUtil.getExplainPlan(rs);
        assertEquals("CLIENT PARALLEL 1-WAY FULL SCAN OVER T2\n" + "    SERVER FILTER BY FIRST KEY ONLY\n" + "    PARALLEL INNER-JOIN TABLE 0\n" + "        CLIENT PARALLEL 1-WAY RANGE SCAN OVER IDX ['foobar']\n" + "            SERVER FILTER BY FIRST KEY ONLY\n" + "    DYNAMIC SERVER FILTER BY B.K IN (\"A.:K\")", explainPlan);
    } finally {
        conn.close();
    }
}

@Test
public void testSaltTableJoin() throws Exception {
    PhoenixConnection conn = (PhoenixConnection) DriverManager.getConnection(getUrl());
    try {
        conn.createStatement().execute("drop table if exists SALT_TEST2900");
        conn.createStatement().execute("create table SALT_TEST2900" + "(" + "id UNSIGNED_INT not null primary key," + "appId VARCHAR" + ")SALT_BUCKETS=2");
        conn.createStatement().execute("drop table if exists RIGHT_TEST2900 ");
        conn.createStatement().execute("create table RIGHT_TEST2900" + "(" + "appId VARCHAR not null primary key," + "createTime VARCHAR" + ")");
        String sql = "select * from SALT_TEST2900 a inner join RIGHT_TEST2900 b on a.appId=b.appId where a.id>=3 and a.id<=5";
        HashJoinPlan plan = (HashJoinPlan) getQueryPlan(sql, Collections.emptyList());
        ScanRanges ranges = plan.getContext().getScanRanges();
        List<HRegionLocation> regionLocations = conn.getQueryServices().getAllTableRegions(Bytes.toBytes("SALT_TEST2900"));
        for (HRegionLocation regionLocation : regionLocations) {
            assertTrue(ranges.intersectRegion(regionLocation.getRegion().getStartKey(), regionLocation.getRegion().getEndKey(), false));
        }
    } finally {
        conn.close();
    }
}

