        assertTrue(queryPlan.getGroupBy().getKeyExpressions().get(0).getSortOrder() == SortOrder.DESC);
        assertTrue(queryPlan.getGroupBy().getKeyExpressions().get(1).getSortOrder() == SortOrder.DESC);
