        TestUtil.assertSelectStatement(rhsPlan.getStatement(), "SELECT ENTITY_ID ID,A_STRING A,B_STRING B,A_BYTE X FROM TESTA  WHERE A_BYTE != 5 ORDER BY B_STRING");
    } finally {
        conn.close();
    }
}

