@Test
public void testTrailingRangesIterator() throws Exception {
    KeyRange[] all = new KeyRange[] { EVERYTHING_RANGE, EVERYTHING_RANGE, EVERYTHING_RANGE, EVERYTHING_RANGE, EVERYTHING_RANGE, EVERYTHING_RANGE };
    List<KeyRange[]> singleAll = Collections.singletonList(all);
    KeyRange[] r1 = new KeyRange[] { EVERYTHING_RANGE, EVERYTHING_RANGE, EVERYTHING_RANGE, getKeyRange(Bytes.toBytes("A")), EVERYTHING_RANGE, EVERYTHING_RANGE };
    KeyRange[] r2 = new KeyRange[] { EVERYTHING_RANGE, EVERYTHING_RANGE, EVERYTHING_RANGE, getKeyRange(Bytes.toBytes("B")), EVERYTHING_RANGE, EVERYTHING_RANGE };
    KeyRange[] r3 = new KeyRange[] { EVERYTHING_RANGE, EVERYTHING_RANGE, EVERYTHING_RANGE, getKeyRange(Bytes.toBytes("C")), EVERYTHING_RANGE, EVERYTHING_RANGE };
    KeyRange[] r4 = new KeyRange[] { EVERYTHING_RANGE, EVERYTHING_RANGE, EVERYTHING_RANGE, getKeyRange(Bytes.toBytes("D")), EVERYTHING_RANGE, EVERYTHING_RANGE };
    KeyRange[] r5 = new KeyRange[] { EVERYTHING_RANGE, EVERYTHING_RANGE, EVERYTHING_RANGE, getKeyRange(Bytes.toBytes("A"), true, Bytes.toBytes("D"), true), EVERYTHING_RANGE, EVERYTHING_RANGE };
    int initPkPos = 1;
    int pkPos = 3;
    List<List<List<KeyRange[]>>> slotsTrailingRangesList = Lists.<List<List<KeyRange[]>>>newArrayList(Lists.<List<KeyRange[]>>newArrayList(Lists.<KeyRange[]>newArrayList(r5)), Lists.<List<KeyRange[]>>newArrayList(Lists.<KeyRange[]>newArrayList(r1, r2), Lists.<KeyRange[]>newArrayList(r3, r4)), Lists.<List<KeyRange[]>>newArrayList(), Lists.<List<KeyRange[]>>newArrayList(singleAll));
    List<KeyRange> results = Lists.<KeyRange>newArrayList();
    List<KeyRange> expectedResults = Lists.newArrayList(getKeyRange(Bytes.toBytes("A")), getKeyRange(Bytes.toBytes("B")), getKeyRange(Bytes.toBytes("C")), getKeyRange(Bytes.toBytes("D")));
    TrailingRangeIterator iterator = new TrailingRangeIterator(initPkPos, pkPos, slotsTrailingRangesList);
    while (iterator.hasNext()) {
        do {
            do {
                KeyRange range = iterator.getRange();
                results.add(range);
            } while (iterator.nextTrailingRange());
        } while (iterator.nextRange());
    }
    assertEquals(expectedResults, results);
}

@Test
public void testSlotsIterator() throws Exception {
    List<KeySlots> keySlotsList = Lists.newArrayList();
    keySlotsList.add(new SingleKeySlot(null, 0, Lists.<KeyRange>newArrayList(KeyRange.getKeyRange(Bytes.toBytes("A")), KeyRange.getKeyRange(Bytes.toBytes("B")))));
    keySlotsList.add(new SingleKeySlot(null, 1, Lists.<KeyRange>newArrayList(KeyRange.getKeyRange(Bytes.toBytes("C")))));
    keySlotsList.add(new SingleKeySlot(null, 0, Lists.<KeyRange>newArrayList(KeyRange.getKeyRange(Bytes.toBytes("D")), KeyRange.getKeyRange(Bytes.toBytes("E")))));
    keySlotsList.add(new SingleKeySlot(null, 1, Lists.<KeyRange>newArrayList()));
    SlotsIterator iterator = new SlotsIterator(keySlotsList, 0);
    String[][] expectedResults = { { "A", null, "D", null }, { "B", null, "D", null }, { "A", null, "E", null }, { "B", null, "E", null } };
    int j = 0;
    while (iterator.next()) {
        int i;
        for (i = 0; i < keySlotsList.size(); i++) {
            KeyRange range = iterator.getRange(i);
            String result = range == null ? null : Bytes.toString(range.getLowerRange());
            String expectedResult = expectedResults[j][i];
            assertEquals(expectedResult, result);
        }
        assertEquals(i, expectedResults[j].length);
        j++;
    }
    assertEquals(j, expectedResults.length);
}

