    Date endDate = DateUtil.parseDate("2012-01-01 12:00:00");
    String query = "select * from ptsdb where inst=? and host=? and round(date,'DAY')=?";
    List<Object> binds = Arrays.<Object>asList(inst, host, roundDate);
