    assertArrayEquals(startRow, scan.getStartRow());
    assertTrue(scan.includeStartRow());
    byte[] stopRow = ByteUtil.concat(PVarchar.INSTANCE.toBytes(inst), QueryConstants.SEPARATOR_BYTE_ARRAY, PVarchar.INSTANCE.toBytes(host), QueryConstants.SEPARATOR_BYTE_ARRAY, PDate.INSTANCE.toBytes(endDate));
    assertArrayEquals(stopRow, scan.getStopRow());
    assertFalse(scan.includeStopRow());
}

