        assertNull(scan.getFilter());
        assertArrayEquals(scan.getStartRow(), PInteger.INSTANCE.toBytes(2));
        assertArrayEquals(scan.getStopRow(), PInteger.INSTANCE.toBytes(5));
        //case 7: pk1 or pk2,but pk2 is all range
