        scan = queryPlan.getContext().getScan();
        assertTrue(scan.getFilter() instanceof SkipScanFilter);
        rowKeyRanges = ((SkipScanFilter) (scan.getFilter())).getSlots();
        assertEquals(Arrays.asList(Arrays.asList(KeyRange.EVERYTHING_RANGE), Arrays.asList(KeyRange.getKeyRange(PInteger.INSTANCE.toBytes(4), true, PInteger.INSTANCE.toBytes(6), false), KeyRange.getKeyRange(PInteger.INSTANCE.toBytes(8), true, PInteger.INSTANCE.toBytes(9), false))), rowKeyRanges);
        assertArrayEquals(scan.getStartRow(), HConstants.EMPTY_START_ROW);
        assertArrayEquals(scan.getStopRow(), HConstants.EMPTY_END_ROW);
    } finally {
