@Test
public void testImmediateCertainty() {
    testImmediate(true, true, true);
    testImmediate(false, false, true);
    testImmediate(false, false, false);
}

@Test
public void testImmediateUncertainty() {
    testImmediate(null, true, null);
    testImmediate(false, false, null);
    testImmediate(null, null, null);
}

@Test
public void testPartialCertainty() {
    // T AND T = T
    // must evaluate both sides, regardless of order
    testPartialEvaluation(true, true, true, true);
    testPartialEvaluation(true, true, true, false);
    // T AND F = F
    // must evaluate both sides if TRUE is evaluated first
    testPartialEvaluation(false, true, false, true);
    testPartialEvaluation(false, false, true, false);
}

@Test
public void testPartialUncertainty() {
    // T AND NULL = NULL
    // must evaluate both sides, regardless of order of values or evaluation
    testPartialEvaluation(null, true, null, true);
    testPartialEvaluation(null, true, null, false);
    testPartialEvaluation(null, null, true, true);
    testPartialEvaluation(null, null, true, false);
    // must evaluate both sides if NULL is evaluated first
    // F AND NULL = FALSE
    testPartialEvaluation(false, null, false, true);
    testPartialEvaluation(false, false, null, false);
    // NULL AND NULL = NULL
    testPartialEvaluation(null, null, null, true);
    testPartialEvaluation(null, null, null, false);
}

@Test
public void testShortCircuitCertainty() {
    // need only to evaluate one side if FALSE is evaluated first
    // F AND F = F
    testShortCircuit(false, false, false, true);
    testShortCircuit(false, false, false, false);
    // T AND F = F
    testShortCircuit(false, false, true, true);
    testShortCircuit(false, true, false, false);
}

@Test
public void testShortCircuitUncertainty() {
    // need only to evaluate one side if FALSE is evaluated first
    // F AND NULL = FALSE
    testShortCircuit(false, false, null, true);
    testShortCircuit(false, null, false, false);
}

@Test
public void testTruthTable() {
    // See: https://en.wikipedia.org/wiki/Null_(SQL)#Comparisons_with_NULL_and_the_three-valued_logic_(3VL)
    Boolean[][] testCases = new Boolean[][] { //              should short circuit?
    //    X,     Y, if X first, if Y first, X AND Y,
    { true, true, false, false, true }, { true, false, false, true, false }, { false, false, true, true, false }, { true, null, false, false, null }, { false, null, true, false, false }, { null, null, false, false, null } };
    for (Boolean[] testCase : testCases) {
        Boolean x = testCase[0];
        Boolean y = testCase[1];
        boolean shouldShortCircuitWhenXEvaluatedFirst = testCase[2];
        boolean shouldShortCircuitWhenYEvaluatedFirst = testCase[3];
        Boolean expected = testCase[4];
        // test both directions
        testImmediate(expected, x, y);
        if (shouldShortCircuitWhenXEvaluatedFirst) {
            testShortCircuit(expected, x, y, true);
        } else {
            testPartialEvaluation(expected, x, y, true);
        }
        if (shouldShortCircuitWhenYEvaluatedFirst) {
            testShortCircuit(expected, x, y, false);
        } else {
            testPartialEvaluation(expected, x, y, false);
        }
    }
}

// Addition
// result scale should be: max(ls, rs)
// result precision should be: max(lp - ls, rp - rs) + 1 + max(ls, rs)
@Test
public void testDecimalAddition() throws Exception {
    LiteralExpression op1, op2, op3;
    List<Expression> children;
    DecimalAddExpression e;
    op1 = LiteralExpression.newConstant(new BigDecimal("1234567890123456789012345678901"), PDecimal.INSTANCE, 31, 0);
    op2 = LiteralExpression.newConstant(new BigDecimal("12345"), PDecimal.INSTANCE, 5, 0);
    children = Arrays.<Expression>asList(op1, op2);
    e = new DecimalAddExpression(children);
    assertEqualValue(e, PDecimal.INSTANCE, new BigDecimal("1234567890123456789012345691246"));
    op1 = LiteralExpression.newConstant(new BigDecimal("12345"), PDecimal.INSTANCE, 5, 0);
    op2 = LiteralExpression.newConstant(new BigDecimal("123.45"), PDecimal.INSTANCE, 5, 2);
    children = Arrays.<Expression>asList(op1, op2);
    e = new DecimalAddExpression(children);
    assertEqualValue(e, PDecimal.INSTANCE, new BigDecimal("12468.45"));
    // Exceeds precision.
    op1 = LiteralExpression.newConstant(new BigDecimal("99999999999999999999999999999999999999"), PDecimal.INSTANCE, 38, 0);
    op2 = LiteralExpression.newConstant(new BigDecimal("123"), PDecimal.INSTANCE, 3, 0);
    children = Arrays.<Expression>asList(op1, op2);
    e = new DecimalAddExpression(children);
    try {
        e.evaluate(null, new ImmutableBytesWritable());
        fail("Evaluation should have failed");
    } catch (DataExceedsCapacityException ex) {
    }
    // Pass since we roll out imposing precisioin and scale.
    op1 = LiteralExpression.newConstant(new BigDecimal("99999999999999999999999999999999999999"), PDecimal.INSTANCE, 38, 0);
    op2 = LiteralExpression.newConstant(new BigDecimal("123"), PDecimal.INSTANCE, 3, 0);
    op3 = LiteralExpression.newConstant(new BigDecimal("-123"), PDecimal.INSTANCE, 3, 0);
    children = Arrays.<Expression>asList(op1, op2, op3);
    e = new DecimalAddExpression(children);
    assertEqualValue(e, PDecimal.INSTANCE, new BigDecimal("99999999999999999999999999999999999999"));
    // Exceeds scale.
    op1 = LiteralExpression.newConstant(new BigDecimal("12345678901234567890123456789012345678"), PDecimal.INSTANCE, 38, 0);
    op2 = LiteralExpression.newConstant(new BigDecimal("123.45"), PDecimal.INSTANCE, 5, 2);
    children = Arrays.<Expression>asList(op1, op2);
    e = new DecimalAddExpression(children);
    try {
        e.evaluate(null, new ImmutableBytesWritable());
        fail("Evaluation should have failed");
    } catch (DataExceedsCapacityException ex) {
    }
    // Decimal with no precision and scale.
    op1 = LiteralExpression.newConstant(new BigDecimal("9999.1"), PDecimal.INSTANCE);
    op2 = LiteralExpression.newConstant(new BigDecimal("1.1111"), PDecimal.INSTANCE, 5, 4);
    children = Arrays.<Expression>asList(op1, op2);
    e = new DecimalAddExpression(children);
    assertEqualValue(e, PDecimal.INSTANCE, new BigDecimal("10000.2111"));
}

