// The three tests below are backported from PHOENIX-5066.
// When PHOENIX-5066 lands, these can be removed as redundant.
@Test
public void testRoundingGMT() throws SQLException {
    // We operate on Instants for time units up to Days, simply counting millis
    RoundDateExpression oddWholeSecondExp = getRoundMsExpression("2022-11-11 11:11:11", TimeUnit.SECOND, 1);
    java.sql.Timestamp oddWholeSecond = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:11:11").getTime());
    long lowerBoundaryOddWholeSecond = oddWholeSecond.getTime() - HALF_SEC;
    long upperBoundaryOddWholeSecond = oddWholeSecond.getTime() + HALF_SEC - 1;
    assertEquals(lowerBoundaryOddWholeSecond, oddWholeSecondExp.rangeLower(oddWholeSecond.getTime()));
    assertEquals(upperBoundaryOddWholeSecond, oddWholeSecondExp.rangeUpper(oddWholeSecond.getTime()));
    assertEquals(oddWholeSecond, new java.sql.Timestamp(oddWholeSecondExp.roundTime(lowerBoundaryOddWholeSecond)));
    assertNotEquals(oddWholeSecond, new java.sql.Timestamp(oddWholeSecondExp.roundTime(lowerBoundaryOddWholeSecond - 1)));
    assertEquals(oddWholeSecond, new java.sql.Timestamp(oddWholeSecondExp.roundTime(upperBoundaryOddWholeSecond)));
    assertNotEquals(oddWholeSecond, new java.sql.Timestamp(oddWholeSecondExp.roundTime(upperBoundaryOddWholeSecond + 1)));
    // 10 sec range
    RoundDateExpression oddWholeSecondRound10Exp = getRoundMsExpression("2022-11-11 11:11:10", TimeUnit.SECOND, 10);
    java.sql.Timestamp oddWholeSecondRound10 = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:11:10").getTime());
    long lowerBoundaryOddWholeSecondRound10 = oddWholeSecondRound10.getTime() - 5 * SEC;
    long upperBoundaryOddWholeSecondRound10 = oddWholeSecondRound10.getTime() + 5 * SEC - 1;
    assertEquals(lowerBoundaryOddWholeSecondRound10, oddWholeSecondRound10Exp.rangeLower(oddWholeSecond.getTime()));
    assertEquals(upperBoundaryOddWholeSecondRound10, oddWholeSecondRound10Exp.rangeUpper(oddWholeSecond.getTime()));
    assertEquals(oddWholeSecondRound10, new java.sql.Timestamp(oddWholeSecondRound10Exp.roundTime(lowerBoundaryOddWholeSecondRound10)));
    assertNotEquals(oddWholeSecondRound10, new java.sql.Timestamp(oddWholeSecondRound10Exp.roundTime(lowerBoundaryOddWholeSecondRound10 - 1)));
    assertEquals(oddWholeSecondRound10, new java.sql.Timestamp(oddWholeSecondRound10Exp.roundTime(upperBoundaryOddWholeSecondRound10)));
    assertNotEquals(oddWholeSecondRound10, new java.sql.Timestamp(oddWholeSecondRound10Exp.roundTime(upperBoundaryOddWholeSecondRound10 + 1)));
    // 15 sec range
    RoundDateExpression oddWholeSecondRound15Exp = getRoundMsExpression("2022-11-11 11:11:15", TimeUnit.SECOND, 15);
    java.sql.Timestamp oddWholeSecondRound15 = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:11:15").getTime());
    long lowerBoundaryOddWholeSecondRound15 = oddWholeSecondRound15.getTime() - 15 * HALF_SEC;
    long upperBoundaryOddWholeSecondRound15 = oddWholeSecondRound15.getTime() + 15 * HALF_SEC - 1;
    assertEquals(lowerBoundaryOddWholeSecondRound15, oddWholeSecondRound15Exp.rangeLower(oddWholeSecond.getTime()));
    assertEquals(upperBoundaryOddWholeSecondRound15, oddWholeSecondRound15Exp.rangeUpper(oddWholeSecond.getTime()));
    assertEquals(oddWholeSecondRound15, new java.sql.Timestamp(oddWholeSecondRound15Exp.roundTime(lowerBoundaryOddWholeSecondRound15)));
    assertNotEquals(oddWholeSecondRound15, new java.sql.Timestamp(oddWholeSecondRound15Exp.roundTime(lowerBoundaryOddWholeSecondRound15 - 1)));
    assertEquals(oddWholeSecondRound15, new java.sql.Timestamp(oddWholeSecondRound15Exp.roundTime(upperBoundaryOddWholeSecondRound15)));
    assertNotEquals(oddWholeSecondRound15, new java.sql.Timestamp(oddWholeSecondRound15Exp.roundTime(upperBoundaryOddWholeSecondRound15 + 1)));
    RoundDateExpression evenWholeSecondExp = getRoundMsExpression("2022-11-11 11:11:12", TimeUnit.SECOND, 1);
    java.sql.Timestamp evenWholeSecond = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:11:12").getTime());
    long lowerBoundaryEvenWholeSecond = evenWholeSecond.getTime() - HALF_SEC;
    long upperBoundaryEvenWholeSecond = evenWholeSecond.getTime() + HALF_SEC - 1;
    assertEquals(lowerBoundaryEvenWholeSecond, evenWholeSecondExp.rangeLower(evenWholeSecond.getTime()));
    assertEquals(upperBoundaryEvenWholeSecond, evenWholeSecondExp.rangeUpper(evenWholeSecond.getTime()));
    assertEquals(evenWholeSecond, new java.sql.Timestamp(evenWholeSecondExp.roundTime(lowerBoundaryEvenWholeSecond)));
    assertNotEquals(evenWholeSecond, new java.sql.Timestamp(evenWholeSecondExp.roundTime(lowerBoundaryEvenWholeSecond - 1)));
    assertEquals(evenWholeSecond, new java.sql.Timestamp(evenWholeSecondExp.roundTime(upperBoundaryEvenWholeSecond)));
    assertNotEquals(evenWholeSecond, new java.sql.Timestamp(evenWholeSecondExp.roundTime(upperBoundaryEvenWholeSecond + 1)));
    RoundDateExpression oddWholeMinuteExp = getRoundMsExpression("2022-11-11 11:11:0", TimeUnit.MINUTE, 1);
    java.sql.Timestamp oddWholeMinute = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:11:0").getTime());
    long lowerBoundaryOddWholeMinute = oddWholeMinute.getTime() - HALF_MIN;
    long upperBoundaryOddWholeMinute = oddWholeMinute.getTime() + HALF_MIN - 1;
    assertEquals(lowerBoundaryOddWholeMinute, oddWholeMinuteExp.rangeLower(oddWholeMinute.getTime()));
    assertEquals(upperBoundaryOddWholeMinute, oddWholeMinuteExp.rangeUpper(oddWholeMinute.getTime()));
    assertEquals(oddWholeMinute, new java.sql.Timestamp(oddWholeMinuteExp.roundTime(lowerBoundaryOddWholeMinute)));
    assertNotEquals(oddWholeMinute, new java.sql.Timestamp(oddWholeMinuteExp.roundTime(lowerBoundaryOddWholeMinute - 1)));
    assertEquals(oddWholeMinute, new java.sql.Timestamp(oddWholeMinuteExp.roundTime(upperBoundaryOddWholeMinute)));
    assertNotEquals(oddWholeMinute, new java.sql.Timestamp(oddWholeMinuteExp.roundTime(upperBoundaryOddWholeMinute + 1)));
    RoundDateExpression oddWholeMinuteRound20Exp = getRoundMsExpression("2022-11-11 11:20:0", TimeUnit.MINUTE, 20);
    java.sql.Timestamp oddWholeMinuteRound20 = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:20:0").getTime());
    long lowerBoundaryOddWholeMinute20 = oddWholeMinuteRound20.getTime() - 10 * MIN;
    long upperBoundaryOddWholeMinute20 = oddWholeMinuteRound20.getTime() + 10 * MIN - 1;
    assertEquals(lowerBoundaryOddWholeMinute20, oddWholeMinuteRound20Exp.rangeLower(oddWholeMinute.getTime()));
