    assertNotEquals(oddWholeMinuteRound20, new java.sql.Timestamp(oddWholeMinuteRound20Exp.roundTime(upperBoundaryOddWholeMinute20 + 1)));
    // Minutes since epoch, don't expect the rounded value to be "round"
    RoundDateExpression oddWholeMinuteRound17Exp = getRoundMsExpression("2022-11-11 11:12:0", TimeUnit.MINUTE, 17);
    java.sql.Timestamp oddWholeMinuteRound17 = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:12:00").getTime());
    long lowerBoundaryOddWholeMinute17 = oddWholeMinuteRound17.getTime() - 17 * HALF_MIN;
