    assertEquals(oddWholeMinuteRound17, new java.sql.Timestamp(oddWholeMinuteRound17Exp.roundTime(upperBoundaryOddWholeMinute17)));
    assertNotEquals(oddWholeMinuteRound17, new java.sql.Timestamp(oddWholeMinuteRound17Exp.roundTime(upperBoundaryOddWholeMinute17 + 1)));
    RoundDateExpression evenWholeMinuteExp = getRoundMsExpression("2022-11-11 11:12:0", TimeUnit.MINUTE, 1);
    java.sql.Timestamp evenWholeMinute = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:12:0").getTime());
    long lowerBoundaryEvenWholeMinute = evenWholeMinute.getTime() - HALF_MIN;
