@Test
public void testFloorGMT() throws SQLException {
    // No need to repeat odd / even cases
    // The logic for upper and lower scan ranges is always
    // [floor(ts), ceil(ts+1)-1]
    RoundDateExpression oddWholeSecondExp = getFloorMsExpression("2022-11-11 11:11:11", TimeUnit.SECOND, 1);
    java.sql.Timestamp oddWholeSecond = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:11:11").getTime());
    long lowerBoundaryOddWholeSecond = oddWholeSecond.getTime();
    long upperBoundaryOddWholeSecond = oddWholeSecond.getTime() + SEC - 1;
    assertEquals(lowerBoundaryOddWholeSecond, oddWholeSecondExp.rangeLower(oddWholeSecond.getTime()));
    assertEquals(upperBoundaryOddWholeSecond, oddWholeSecondExp.rangeUpper(oddWholeSecond.getTime()));
    assertEquals(oddWholeSecond, new java.sql.Timestamp(oddWholeSecondExp.roundTime(lowerBoundaryOddWholeSecond)));
    assertNotEquals(oddWholeSecond, new java.sql.Timestamp(oddWholeSecondExp.roundTime(lowerBoundaryOddWholeSecond - 1)));
    assertEquals(oddWholeSecond, new java.sql.Timestamp(oddWholeSecondExp.roundTime(upperBoundaryOddWholeSecond)));
    assertNotEquals(oddWholeSecond, new java.sql.Timestamp(oddWholeSecondExp.roundTime(upperBoundaryOddWholeSecond + 1)));
    // 10 sec range
    RoundDateExpression oddWholeSecondFloor10Exp = getFloorMsExpression("2022-11-11 11:11:10", TimeUnit.SECOND, 10);
    java.sql.Timestamp oddWholeSecondFloor10 = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:11:10").getTime());
    long lowerBoundaryOddWholeSecondFloor10 = oddWholeSecondFloor10.getTime();
    long upperBoundaryOddWholeSecondFloor10 = oddWholeSecondFloor10.getTime() + 10 * SEC - 1;
    assertEquals(lowerBoundaryOddWholeSecondFloor10, oddWholeSecondFloor10Exp.rangeLower(oddWholeSecond.getTime()));
    assertEquals(upperBoundaryOddWholeSecondFloor10, oddWholeSecondFloor10Exp.rangeUpper(oddWholeSecond.getTime()));
    assertEquals(oddWholeSecondFloor10, new java.sql.Timestamp(oddWholeSecondFloor10Exp.roundTime(lowerBoundaryOddWholeSecondFloor10)));
    assertNotEquals(oddWholeSecondFloor10, new java.sql.Timestamp(oddWholeSecondFloor10Exp.roundTime(lowerBoundaryOddWholeSecondFloor10 - 1)));
    assertEquals(oddWholeSecondFloor10, new java.sql.Timestamp(oddWholeSecondFloor10Exp.roundTime(upperBoundaryOddWholeSecondFloor10)));
    assertNotEquals(oddWholeSecondFloor10, new java.sql.Timestamp(oddWholeSecondFloor10Exp.roundTime(upperBoundaryOddWholeSecondFloor10 + 1)));
    // 15 sec range
    RoundDateExpression oddWholeSecondFloor15Exp = getFloorMsExpression("2022-11-11 11:11:0", TimeUnit.SECOND, 15);
    java.sql.Timestamp oddWholeSecondFloor15 = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:11:0").getTime());
    long lowerBoundaryOddWholeSecondFloor15 = oddWholeSecondFloor15.getTime();
