    assertNotEquals(oddWholeSecondFloor15, new java.sql.Timestamp(oddWholeSecondFloor15Exp.roundTime(upperBoundaryOddWholeSecondFloor15 + 1)));
    RoundDateExpression evenWholeMinuteExp = getFloorMsExpression("2022-11-11 11:12:0", TimeUnit.MINUTE, 1);
    java.sql.Timestamp evenWholeMinute = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:12:0").getTime());
    long lowerBoundaryEvenWholeMinute = evenWholeMinute.getTime();
    long upperBoundaryEvenWholeMinute = evenWholeMinute.getTime() + MIN - 1;
    assertEquals(lowerBoundaryEvenWholeMinute, evenWholeMinuteExp.rangeLower(evenWholeMinute.getTime()));
    assertEquals(upperBoundaryEvenWholeMinute, evenWholeMinuteExp.rangeUpper(evenWholeMinute.getTime()));
    assertEquals(evenWholeMinute, new java.sql.Timestamp(evenWholeMinuteExp.roundTime(lowerBoundaryEvenWholeMinute)));
    assertNotEquals(evenWholeMinute, new java.sql.Timestamp(evenWholeMinuteExp.roundTime(lowerBoundaryEvenWholeMinute - 1)));
    assertEquals(evenWholeMinute, new java.sql.Timestamp(evenWholeMinuteExp.roundTime(upperBoundaryEvenWholeMinute)));
    assertNotEquals(evenWholeMinute, new java.sql.Timestamp(evenWholeMinuteExp.roundTime(upperBoundaryEvenWholeMinute + 1)));
    RoundDateExpression evenWholeMinuteFloor20Exp = getFloorMsExpression("2022-11-11 11:00:0", TimeUnit.MINUTE, 20);
    java.sql.Timestamp evenWholeMinuteFloor20 = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:00:0").getTime());
