    assertNotEquals(evenWholeMinuteFloor20, new java.sql.Timestamp(evenWholeMinuteFloor20Exp.roundTime(upperBoundaryEvenWholeMinuteFloor20 + 1)));
    // Minutes since epoch, don't expect the rounded value to be "round"
    RoundDateExpression evenWholeMinuteFloor17Exp = getFloorMsExpression("2022-11-11 11:12:00", TimeUnit.MINUTE, 17);
    java.sql.Timestamp evenWholeMinuteFloor17 = new java.sql.Timestamp(DateUtil.parseDate("2022-11-11 11:12:00").getTime());
    long lowerBoundaryEvenWholeMinute17 = evenWholeMinuteFloor17.getTime();
