    long lowerBoundaryEvenWholeDay3 = evenWholeDay3.getTime() - 3 * DAY + 1;
    long upperBoundaryEvenWholeDay3 = evenWholeDay3.getTime();
    assertEquals(lowerBoundaryEvenWholeDay3, evenWholeDay3Exp.rangeLower(evenWholeDay.getTime()));
    assertEquals(upperBoundaryEvenWholeDay3, evenWholeDay3Exp.rangeUpper(evenWholeDay.getTime()));
    assertEquals(evenWholeDay3, new java.sql.Timestamp(evenWholeDay3Exp.roundTime(lowerBoundaryEvenWholeDay3)));
    assertNotEquals(evenWholeDay3, new java.sql.Timestamp(evenWholeDay3Exp.roundTime(lowerBoundaryEvenWholeDay3 - 1)));
    assertEquals(evenWholeDay3, new java.sql.Timestamp(evenWholeDay3Exp.roundTime(upperBoundaryEvenWholeDay3)));
    assertNotEquals(evenWholeDay3, new java.sql.Timestamp(evenWholeDay3Exp.roundTime(upperBoundaryEvenWholeDay3 + 1)));
    CeilWeekExpression ceilWeekExp = new CeilWeekExpression();
    java.sql.Timestamp wholeWeekOdd = new java.sql.Timestamp(DateUtil.parseDate("2022-10-10 0:0:0").getTime());
    long lowerBoundaryWholeWeekOdd = wholeWeekOdd.getTime() - WEEK + 1;
    long upperBoundaryWholeWeekOdd = wholeWeekOdd.getTime();
    assertEquals(lowerBoundaryWholeWeekOdd, ceilWeekExp.rangeLower(wholeWeekOdd.getTime()));
    assertEquals(upperBoundaryWholeWeekOdd, ceilWeekExp.rangeUpper(wholeWeekOdd.getTime()));
    assertEquals(wholeWeekOdd, new java.sql.Timestamp(ceilWeekExp.roundDateTime(new org.joda.time.DateTime(lowerBoundaryWholeWeekOdd, GJChronology.getInstanceUTC()))));
    assertNotEquals(wholeWeekOdd, new java.sql.Timestamp(ceilWeekExp.roundDateTime(new org.joda.time.DateTime(lowerBoundaryWholeWeekOdd - 1, GJChronology.getInstanceUTC()))));
    assertEquals(wholeWeekOdd, new java.sql.Timestamp(ceilWeekExp.roundDateTime(new org.joda.time.DateTime(upperBoundaryWholeWeekOdd, GJChronology.getInstanceUTC()))));
    assertNotEquals(wholeWeekOdd, new java.sql.Timestamp(ceilWeekExp.roundDateTime(new org.joda.time.DateTime(upperBoundaryWholeWeekOdd + 1, GJChronology.getInstanceUTC()))));
    CeilMonthExpression ceilMonthExp = new CeilMonthExpression();
    java.sql.Timestamp wholeMonthOdd = new java.sql.Timestamp(DateUtil.parseDate("2022-08-1 0:0:0").getTime());
    // July is 31 days
    long lowerBoundaryWholeMonthOdd = wholeMonthOdd.getTime() - 31 * DAY + 1;
    long upperBoundaryWholeMonthOdd = wholeMonthOdd.getTime();
    assertEquals(lowerBoundaryWholeMonthOdd, ceilMonthExp.rangeLower(wholeMonthOdd.getTime()));
    assertEquals(upperBoundaryWholeMonthOdd, ceilMonthExp.rangeUpper(wholeMonthOdd.getTime()));
    assertEquals(wholeMonthOdd, new java.sql.Timestamp(ceilMonthExp.roundDateTime(new org.joda.time.DateTime(lowerBoundaryWholeMonthOdd, GJChronology.getInstanceUTC()))));
    assertNotEquals(wholeMonthOdd, new java.sql.Timestamp(ceilMonthExp.roundDateTime(new org.joda.time.DateTime(lowerBoundaryWholeMonthOdd - 1, GJChronology.getInstanceUTC()))));
    assertEquals(wholeMonthOdd, new java.sql.Timestamp(ceilMonthExp.roundDateTime(new org.joda.time.DateTime(upperBoundaryWholeMonthOdd, GJChronology.getInstanceUTC()))));
    assertNotEquals(wholeMonthOdd, new java.sql.Timestamp(ceilMonthExp.roundDateTime(new org.joda.time.DateTime(upperBoundaryWholeMonthOdd + 1, GJChronology.getInstanceUTC()))));
    java.sql.Timestamp wholeMonthLeap = new java.sql.Timestamp(DateUtil.parseDate("2024-03-1 0:0:0").getTime());
    // February is 29 days
    long lowerBoundaryWholeMonthLeap = wholeMonthLeap.getTime() - 29 * DAY + 1;
    long upperBoundaryWholeMonthLeap = wholeMonthLeap.getTime();
    assertEquals(lowerBoundaryWholeMonthLeap, ceilMonthExp.rangeLower(wholeMonthLeap.getTime()));
    assertEquals(upperBoundaryWholeMonthLeap, ceilMonthExp.rangeUpper(wholeMonthLeap.getTime()));
    assertEquals(wholeMonthLeap, new java.sql.Timestamp(ceilMonthExp.roundDateTime(new org.joda.time.DateTime(lowerBoundaryWholeMonthLeap, GJChronology.getInstanceUTC()))));
    assertNotEquals(wholeMonthLeap, new java.sql.Timestamp(ceilMonthExp.roundDateTime(new org.joda.time.DateTime(lowerBoundaryWholeMonthLeap - 1, GJChronology.getInstanceUTC()))));
    assertEquals(wholeMonthLeap, new java.sql.Timestamp(ceilMonthExp.roundDateTime(new org.joda.time.DateTime(upperBoundaryWholeMonthLeap, GJChronology.getInstanceUTC()))));
    assertNotEquals(wholeMonthLeap, new java.sql.Timestamp(ceilMonthExp.roundDateTime(new org.joda.time.DateTime(upperBoundaryWholeMonthLeap + 1, GJChronology.getInstanceUTC()))));
    CeilYearExpression ceilYearExp = new CeilYearExpression();
    java.sql.Timestamp wholeYearEven = new java.sql.Timestamp(DateUtil.parseDate("2022-1-1 0:0:0").getTime());
    long lowerBoundaryWholeYearEven = wholeYearEven.getTime() - YEAR + 1;
    long upperBoundaryWholeYearEven = wholeYearEven.getTime();
    assertEquals(lowerBoundaryWholeYearEven, ceilYearExp.rangeLower(wholeYearEven.getTime()));
    assertEquals(upperBoundaryWholeYearEven, ceilYearExp.rangeUpper(wholeYearEven.getTime()));
    assertEquals(wholeYearEven, new java.sql.Timestamp(ceilYearExp.roundDateTime(new org.joda.time.DateTime(lowerBoundaryWholeYearEven, GJChronology.getInstanceUTC()))));
    assertNotEquals(wholeYearEven, new java.sql.Timestamp(ceilYearExp.roundDateTime(new org.joda.time.DateTime(lowerBoundaryWholeYearEven - 1, GJChronology.getInstanceUTC()))));
    assertEquals(wholeYearEven, new java.sql.Timestamp(ceilYearExp.roundDateTime(new org.joda.time.DateTime(upperBoundaryWholeYearEven, GJChronology.getInstanceUTC()))));
    assertNotEquals(wholeYearEven, new java.sql.Timestamp(ceilYearExp.roundDateTime(new org.joda.time.DateTime(upperBoundaryWholeYearEven + 1, GJChronology.getInstanceUTC()))));
    java.sql.Timestamp wholeYearLeapEven = new java.sql.Timestamp(DateUtil.parseDate("2025-1-1 0:0:0").getTime());
    long lowerBoundaryWholeYearLeapEven = wholeYearLeapEven.getTime() - (YEAR + DAY) + 1;
    long upperBoundaryWholeYearLeapEven = wholeYearLeapEven.getTime();
    assertEquals(lowerBoundaryWholeYearLeapEven, ceilYearExp.rangeLower(wholeYearLeapEven.getTime()));
    assertEquals(upperBoundaryWholeYearLeapEven, ceilYearExp.rangeUpper(wholeYearLeapEven.getTime()));
    assertEquals(wholeYearLeapEven, new java.sql.Timestamp(ceilYearExp.roundDateTime(new org.joda.time.DateTime(lowerBoundaryWholeYearLeapEven, GJChronology.getInstanceUTC()))));
    assertNotEquals(wholeYearLeapEven, new java.sql.Timestamp(ceilYearExp.roundDateTime(new org.joda.time.DateTime(lowerBoundaryWholeYearLeapEven - 1, GJChronology.getInstanceUTC()))));
    assertEquals(wholeYearLeapEven, new java.sql.Timestamp(ceilYearExp.roundDateTime(new org.joda.time.DateTime(upperBoundaryWholeYearLeapEven, GJChronology.getInstanceUTC()))));
    assertNotEquals(wholeYearLeapEven, new java.sql.Timestamp(ceilYearExp.roundDateTime(new org.joda.time.DateTime(upperBoundaryWholeYearLeapEven + 1, GJChronology.getInstanceUTC()))));
}

