/**
 * Tests a partial rebuild of a row with multiple versions. 3 versions of the row in data table,
 * and we rebuild the index starting from time t=2
 *
 * There should be one index row version per data row version.
 */
@Test
public void testRebuildMultipleVersionRow() throws IOException {
    // when doing a rebuild, we are replaying mutations so we want to ignore newer mutations
    // see LocalTable#getCurrentRowState()
    Mockito.when(mockIndexMetaData.getReplayWrite()).thenReturn(ReplayWrite.INDEX_ONLY);
    // the current row state has 3 versions, but if we rebuild as of t=2, scanner in LocalTable
    // should only return first
    Cell currentCell1 = PhoenixKeyValueUtil.newKeyValue(ROW, FAM, INDEXED_QUALIFIER, 1, VALUE_1);
    Cell currentCell2 = PhoenixKeyValueUtil.newKeyValue(ROW, FAM, INDEXED_QUALIFIER, 2, VALUE_2);
    Cell currentCell3 = PhoenixKeyValueUtil.newKeyValue(ROW, FAM, INDEXED_QUALIFIER, 3, VALUE_3);
    Cell currentCell4 = PhoenixKeyValueUtil.newKeyValue(ROW, FAM, INDEXED_QUALIFIER, 4, VALUE_4);
    setCurrentRowState(Arrays.asList(currentCell4, currentCell3, currentCell2, currentCell1));
    // rebuilder replays mutations starting from t=2
    MultiMutation mutation = new MultiMutation(new ImmutableBytesPtr(ROW));
    Put put = new Put(ROW);
    put.add(CellBuilderFactory.create(CellBuilderType.SHALLOW_COPY).setRow(put.getRow()).setFamily(FAM).setType(Cell.Type.Put).setQualifier(INDEXED_QUALIFIER).setTimestamp(4).setValue(VALUE_4).build());
    mutation.addAll(put);
    put = new Put(ROW);
    put.add(CellBuilderFactory.create(CellBuilderType.SHALLOW_COPY).setRow(put.getRow()).setFamily(FAM).setType(Cell.Type.Put).setQualifier(INDEXED_QUALIFIER).setTimestamp(3).setValue(VALUE_3).build());
    mutation.addAll(put);
    put = new Put(ROW);
    put.add(CellBuilderFactory.create(CellBuilderType.SHALLOW_COPY).setRow(put.getRow()).setFamily(FAM).setType(Cell.Type.Put).setQualifier(INDEXED_QUALIFIER).setTimestamp(2).setValue(VALUE_2).build());
    mutation.addAll(put);
    Collection<Pair<Mutation, byte[]>> indexUpdates = Lists.newArrayList();
    Collection<? extends Mutation> mutations = IndexManagementUtil.flattenMutationsByTimestamp(Collections.singletonList(mutation));
    CachedLocalTable cachedLocalTable = CachedLocalTable.build(mutations, this.mockIndexMetaData, this.indexBuilder.getEnv().getRegion());
    for (Mutation m : mutations) {
        indexUpdates.addAll(indexBuilder.getIndexUpdate(m, mockIndexMetaData, cachedLocalTable));
    }
    // 3 puts and 3 deletes (one to hide existing index row for VALUE_1, and two to hide index
    // rows for VALUE_2, VALUE_3)
    assertEquals(6, indexUpdates.size());
    assertContains(indexUpdates, 2, ROW, Cell.Type.DeleteFamily, FAM, new byte[0], /* qual not needed */
    2);
    assertContains(indexUpdates, ColumnTracker.NO_NEWER_PRIMARY_TABLE_ENTRY_TIMESTAMP, ROW, Cell.Type.Put, FAM, QueryConstants.EMPTY_COLUMN_BYTES, 2);
    assertContains(indexUpdates, 3, ROW, Cell.Type.DeleteFamily, FAM, new byte[0], /* qual not needed */
    3);
    assertContains(indexUpdates, ColumnTracker.NO_NEWER_PRIMARY_TABLE_ENTRY_TIMESTAMP, ROW, Cell.Type.Put, FAM, QueryConstants.EMPTY_COLUMN_BYTES, 3);
    assertContains(indexUpdates, 4, ROW, Cell.Type.DeleteFamily, FAM, new byte[0], /* qual not needed */
    4);
    assertContains(indexUpdates, ColumnTracker.NO_NEWER_PRIMARY_TABLE_ENTRY_TIMESTAMP, ROW, Cell.Type.Put, FAM, QueryConstants.EMPTY_COLUMN_BYTES, 4);
}

