    Delete dataDel = new Delete(Bytes.toBytes(ROW_KEY));
    addCellToDelMutation(dataDel, info.indexMaintainer.getEmptyKeyValueFamily().copyBytesIfNecessary(), Bytes.toBytes("C1"), 2, Cell.Type.DeleteColumn);
