@Test
public void testIsNewerThan() {
    String haGroupName = testName.getMethodName();
    ClusterRoleRecord recordV0 = new ClusterRoleRecord(haGroupName, HighAvailabilityPolicy.FAILOVER, ZK1, ClusterRole.STANDBY, ZK2, ClusterRole.STANDBY, 0);
    ClusterRoleRecord recordV1 = new ClusterRoleRecord(haGroupName, HighAvailabilityPolicy.FAILOVER, ZK1, ClusterRole.STANDBY, ZK2, ClusterRole.STANDBY, 2);
    // v1 is indeed newer
    assertTrue(recordV1.isNewerThan(recordV0));
    // irreflexive
    assertFalse(recordV1.isNewerThan(recordV1));
    // antisymmetry
    assertFalse(recordV0.isNewerThan(recordV1));
    // Create a new cluster role record for a new HA group name.
    // Cluster role records for different HA groups can not compare in reality,
    // so they are not newer than each other.
    String haGroupName2 = haGroupName + RandomStringUtils.randomAlphabetic(2);
    ClusterRoleRecord record2 = new ClusterRoleRecord(haGroupName2, HighAvailabilityPolicy.FAILOVER, ZK1, ClusterRole.STANDBY, ZK2, ClusterRole.STANDBY, 1);
    assertFalse(recordV0.isNewerThan(record2));
    assertFalse(recordV1.isNewerThan(record2));
    assertFalse(record2.isNewerThan(recordV0));
    assertFalse(record2.isNewerThan(recordV1));
}

