public void testGetUpperBound() {
    // given split policy to be 10 with view size 12
    // we expect 2 mappers with range [0,10) and [10,12)
    assertEquals(10, defaultMultiViewSplitStrategy.getUpperBound(10, 0, 12));
    assertEquals(12, defaultMultiViewSplitStrategy.getUpperBound(10, 1, 12));
    // given split policy to be 8 with view size 12
    // we expect 2 mappers with range [0,8) and [8,12)
    assertEquals(8, defaultMultiViewSplitStrategy.getUpperBound(8, 0, 12));
    assertEquals(12, defaultMultiViewSplitStrategy.getUpperBound(8, 1, 12));
    // given split policy to be 5 with view size 12
    // we expect 1 mappers with range [0,1)
    assertEquals(1, defaultMultiViewSplitStrategy.getUpperBound(5, 0, 1));
}

