    tool.parseArgs(new String[] { "-v", viewName, "-p", "-1" });
    assertEquals("NORMAL", tool.getJobPriority());
    assertEquals(false, tool.isDeletingAllViews());
    assertEquals(viewName, tool.getViewName());
    assertEquals(null, tool.getTenantId());
