        }
    }
    assertTrue(hasPhoenixRowTimestampParseNode);
}

@Test
public void testExpressionWithPhoenixRowTimestampWithParams() throws Exception {
    ParseNode parseNode = SQLParser.parseCondition("(PHOENIX_ROW_TIMESTAMP(COL1) = PK2)");
