        assertFalse("PhoenixRowTimestampFunction does not take any parameters", childNode.getClass().isAssignableFrom(PhoenixRowTimestampParseNode.class));
    }
}

@Test
public void testSelectWithPhoenixRowTimestamp() throws Exception {
