    // test itr.next()
    i = 0;
    while (itr.hasNext()) {
        assertEquals(cells[i++], itr.next());
    }
    assertEquals(7, list.size());
    // test itr.remove()
    itr = list.iterator();
    i = 0;
    int numRemoved = 0;
    try {
