        fail("Remove not allowed till next() is called");
    } catch (IllegalStateException expected) {
    }
    while (itr.hasNext()) {
        assertEquals(cells[i++], itr.next());
        itr.remove();
        numRemoved++;
    }
    assertEquals("Number of elements removed should have been the size of the list", 7, numRemoved);
}

