@Test
public void testStatsBeingAutomaticallyRefreshed() {
    ExecutorService executor = Executors.newFixedThreadPool(4);
    CountDownLatch firstTimeRefreshedSignal = new CountDownLatch(1);
    CountDownLatch secondTimeRefreshedSignal = new CountDownLatch(2);
    Configuration config = HBaseFactoryProvider.getConfigurationFactory().getConfiguration();
    LoadingCache<GuidePostsKey, GuidePostsInfo> cache = CacheBuilder.newBuilder().// Refresh entries a given amount of time after they were written
    refreshAfterWrite(100, TimeUnit.MILLISECONDS).// Maximum total weight (size in bytes) of stats entries
    maximumWeight(QueryServicesOptions.DEFAULT_STATS_MAX_CACHE_SIZE).// Defer actual size to the PTableStats.getEstimatedSize()
    weigher(new Weigher<GuidePostsKey, GuidePostsInfo>() {

        @Override
        public int weigh(GuidePostsKey key, GuidePostsInfo info) {
            return info.getEstimatedSize();
        }
    }).// Log removals at TRACE for debugging
    removalListener(new GuidePostsCacheImpl.PhoenixStatsCacheRemovalListener()).// Automatically load the cache when entries are missing
    build(new PhoenixStatsCacheLoader(new TestStatsLoaderImpl(firstTimeRefreshedSignal, secondTimeRefreshedSignal), config));
    try {
        GuidePostsKey guidePostsKey = new GuidePostsKey(new byte[4], new byte[4]);
        GuidePostsInfo guidePostsInfo = getStats(cache, guidePostsKey);
        assertTrue(guidePostsInfo.getMaxLength() == 1);
        // Note: With Guava cache, automatic refreshes are performed when the first stale request for an entry occurs.
        // After we sleep here for any time which is larger than the refresh cycle, the refresh of cache entry will be
        // triggered for its first time by the call of getStats(). This is deterministic behavior, and it won't cause
        // randomized test failures.
        sleep(150);
        guidePostsInfo = getStats(cache, guidePostsKey);
        // Refresh has been triggered for its first time, but still could get the old value
        assertTrue(guidePostsInfo.getMaxLength() >= 1);
        firstTimeRefreshedSignal.await();
        sleep(150);
        guidePostsInfo = getStats(cache, guidePostsKey);
        // Now the second time refresh has been triggered by the above getStats() call, the first time Refresh has completed
        // and the cache entry has been updated for sure.
        assertTrue(guidePostsInfo.getMaxLength() >= 2);
        secondTimeRefreshedSignal.await();
    } catch (InterruptedException e) {
        assertFalse(true);
    }
}

@Test
public void nonEvictionsAreIgnored() {
    // We don't care so much about cases where we trigger a removal or update of the stats
    // for a table in the cache, but we would want to know about updates happening automatically
    PhoenixStatsCacheRemovalListener listener = new PhoenixStatsCacheRemovalListener();
    // User-driven removals or updates
    assertFalse(listener.wasEvicted(RemovalCause.EXPLICIT));
    assertFalse(listener.wasEvicted(RemovalCause.REPLACED));
    // Automatic removals by the cache itself (per configuration)
    assertTrue(listener.wasEvicted(RemovalCause.COLLECTED));
    assertTrue(listener.wasEvicted(RemovalCause.EXPIRED));
    assertTrue(listener.wasEvicted(RemovalCause.SIZE));
}

