    assertTrue(PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(true), SortOrder.ASC) == PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false), SortOrder.DESC));
    assertTrue(PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(true, SortOrder.ASC)) == PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false, SortOrder.DESC)));
    assertFalse(PBoolean.INSTANCE.toObject(PDataType.FALSE_BYTES, SortOrder.ASC) == PBoolean.INSTANCE.toObject(PDataType.FALSE_BYTES, SortOrder.DESC));
    assertFalse(PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false), SortOrder.ASC) == PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false), SortOrder.DESC));
    assertFalse(PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false, SortOrder.ASC)) == PBoolean.INSTANCE.toObject(PBoolean.INSTANCE.toBytes(false, SortOrder.DESC)));
}

@Test
public void descSortOrderTransformsOp() {
    for (CompareOperator op : CompareOperator.values()) {
        CompareOperator oppositeOp = SortOrder.DESC.transform(op);
        switch(op) {
            case EQUAL:
                assertSame(CompareOperator.EQUAL, oppositeOp);
                break;
            case GREATER:
                assertSame(CompareOperator.LESS, oppositeOp);
                break;
            case GREATER_OR_EQUAL:
                assertSame(CompareOperator.LESS_OR_EQUAL, oppositeOp);
                break;
            case LESS:
                assertSame(CompareOperator.GREATER, oppositeOp);
                break;
            case LESS_OR_EQUAL:
                assertSame(CompareOperator.GREATER_OR_EQUAL, oppositeOp);
                break;
            case NOT_EQUAL:
                assertSame(CompareOperator.NOT_EQUAL, oppositeOp);
                break;
            case NO_OP:
                assertSame(CompareOperator.NO_OP, oppositeOp);
                break;
        }
    }
}

