    assertTrue(PDouble.INSTANCE.compareTo(PDouble.INSTANCE.toBytes(Long.MAX_VALUE + 1025.0), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PLong.INSTANCE.toBytes(Long.MAX_VALUE), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PLong.INSTANCE) > 0);
    assertTrue(PDouble.INSTANCE.compareTo(PDouble.INSTANCE.toBytes(Long.MIN_VALUE - 1024.0), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PLong.INSTANCE.toBytes(Long.MIN_VALUE), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PLong.INSTANCE) == 0);
    assertTrue(PDouble.INSTANCE.compareTo(PDouble.INSTANCE.toBytes(Long.MIN_VALUE - 1025.0), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PLong.INSTANCE.toBytes(Long.MIN_VALUE), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PLong.INSTANCE) < 0);
    // Same as above, but reversing LHS and RHS
    assertTrue(PLong.INSTANCE.compareTo(PLong.INSTANCE.toBytes(1), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE.toBytes(-1e100), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE) > 0);
    assertTrue(PLong.INSTANCE.compareTo(PLong.INSTANCE.toBytes(1), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE.toBytes(0.001), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE) > 0);
    assertTrue(PLong.INSTANCE.compareTo(PLong.INSTANCE.toBytes(Long.MAX_VALUE - 1), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE.toBytes(Long.MAX_VALUE), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE) < 0);
    assertTrue(PLong.INSTANCE.compareTo(PLong.INSTANCE.toBytes(Long.MIN_VALUE + 1), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE.toBytes(Long.MIN_VALUE), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE) > 0);
    assertTrue(PLong.INSTANCE.compareTo(PLong.INSTANCE.toBytes(Long.MIN_VALUE), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE.toBytes(Long.MIN_VALUE), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE) == 0);
    assertTrue(PLong.INSTANCE.compareTo(PLong.INSTANCE.toBytes(Long.MAX_VALUE), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE.toBytes(Long.MAX_VALUE + 1024.0), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE) == 0);
    assertTrue(PLong.INSTANCE.compareTo(PLong.INSTANCE.toBytes(Long.MAX_VALUE), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE.toBytes(Long.MAX_VALUE + 1025.0), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE) < 0);
    assertTrue(PLong.INSTANCE.compareTo(PLong.INSTANCE.toBytes(Long.MIN_VALUE), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE.toBytes(Long.MIN_VALUE - 1024.0), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE) == 0);
    assertTrue(PLong.INSTANCE.compareTo(PLong.INSTANCE.toBytes(Long.MIN_VALUE), 0, PLong.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE.toBytes(Long.MIN_VALUE - 1025.0), 0, PDouble.INSTANCE.getByteSize(), SortOrder.getDefault(), PDouble.INSTANCE) > 0);
    long i = 10;
    long maxl = (1L << 62);
    try {
        for (; i < 100; i++) {
            double d = Math.pow(2, i);
            if ((long) d > maxl) {
                assertTrue(i > 62);
                continue;
            }
            long l = (1L << i) - 1;
            assertTrue(l + 1L == (long) d);
            assertTrue(l < (long) d);
        }
    } catch (AssertionError t) {
        throw t;
    }
    double d = 0.0;
    try {
        while (d <= 1024) {
            double d1 = Long.MAX_VALUE;
            double d2 = Long.MAX_VALUE + d;
            assertTrue(d2 == d1);
            d++;
        }
    } catch (AssertionError t) {
        throw t;
    }
    d = 0.0;
    try {
        while (d >= -1024) {
            double d1 = Long.MIN_VALUE;
            double d2 = Long.MIN_VALUE + d;
            assertTrue(d2 == d1);
            d--;
        }
    } catch (AssertionError t) {
        throw t;
    }
    double d1 = Long.MAX_VALUE;
    double d2 = Long.MAX_VALUE + 1024.0;
    double d3 = Long.MAX_VALUE + 1025.0;
    assertTrue(d1 == d2);
    assertTrue(d3 > d1);
    long l1 = Long.MAX_VALUE - 1;
    assertTrue((long) d1 > l1);
}

@Test
public void testLong() {
    Long la = 4L;
    byte[] b = PLong.INSTANCE.toBytes(la);
    Long lb = (Long) PLong.INSTANCE.toObject(b);
    assertEquals(la, lb);
    Long na = 1L;
    Long nb = -1L;
    byte[] ba = PLong.INSTANCE.toBytes(na);
    byte[] bb = PLong.INSTANCE.toBytes(nb);
    assertTrue(Bytes.compareTo(ba, bb) > 0);
    Integer value = 100;
    Object obj = PLong.INSTANCE.toObject(value, PInteger.INSTANCE);
    assertTrue(obj instanceof Long);
    assertEquals(100, ((Long) obj).longValue());
    Long longValue = 100l;
    Object longObj = PLong.INSTANCE.toObject(longValue, PLong.INSTANCE);
    assertTrue(longObj instanceof Long);
    assertEquals(100, ((Long) longObj).longValue());
    assertEquals(0, PLong.INSTANCE.compareTo(Long.MAX_VALUE, Float.valueOf(Long.MAX_VALUE), PFloat.INSTANCE));
    assertEquals(0, PLong.INSTANCE.compareTo(Long.MAX_VALUE, Double.valueOf(Long.MAX_VALUE), PDouble.INSTANCE));
    assertEquals(-1, PLong.INSTANCE.compareTo(99, Float.valueOf(100), PFloat.INSTANCE));
    assertEquals(1, PLong.INSTANCE.compareTo(101, Float.valueOf(100), PFloat.INSTANCE));
    Double d = -2.0;
    Object lo = PLong.INSTANCE.toObject(d, PDouble.INSTANCE);
    assertEquals(-2L, ((Long) lo).longValue());
    byte[] bytes = PDouble.INSTANCE.toBytes(d);
    lo = PLong.INSTANCE.toObject(bytes, 0, bytes.length, PDouble.INSTANCE);
    assertEquals(-2L, ((Long) lo).longValue());
    Float f = -2.0f;
    lo = PLong.INSTANCE.toObject(f, PFloat.INSTANCE);
    assertEquals(-2L, ((Long) lo).longValue());
    bytes = PFloat.INSTANCE.toBytes(f);
    lo = PLong.INSTANCE.toObject(bytes, 0, bytes.length, PFloat.INSTANCE);
    assertEquals(-2L, ((Long) lo).longValue());
    // Checks for unsignedlong
    d = 2.0;
    lo = PUnsignedLong.INSTANCE.toObject(d, PDouble.INSTANCE);
    assertEquals(2L, ((Long) lo).longValue());
    bytes = PDouble.INSTANCE.toBytes(d);
    lo = PUnsignedLong.INSTANCE.toObject(bytes, 0, bytes.length, PDouble.INSTANCE);
    assertEquals(2L, ((Long) lo).longValue());
    f = 2.0f;
    lo = PUnsignedLong.INSTANCE.toObject(f, PFloat.INSTANCE);
    assertEquals(2L, ((Long) lo).longValue());
    bytes = PFloat.INSTANCE.toBytes(f);
    lo = PUnsignedLong.INSTANCE.toObject(bytes, 0, bytes.length, PFloat.INSTANCE);
    assertEquals(2L, ((Long) lo).longValue());
}

