@Test
public void testArithmeticOnLong() {
    long startWith = -5;
    long incrementBy = 1;
    for (int i = 0; i < 10; i++) {
        long next = nextValueFor(startWith, incrementBy);
        assertEquals(startWith + incrementBy, next);
        startWith = next;
    }
    startWith = 5;
    incrementBy = -1;
    for (int i = 0; i < 10; i++) {
        long next = nextValueFor(startWith, incrementBy);
        assertEquals(startWith + incrementBy, next);
        startWith = next;
    }
