    assertNotNull(cells);
    assertTrue(cells.size() > 0);
    Cell c = cells.get(0);
    assertNotNull("Cell is null!", c);
    assertEquals(serverTimestamp, PLong.INSTANCE.getCodec().decodeLong(CellUtil.cloneValue(c), 0, SortOrder.ASC));
}

