    tsconn.createStatement().execute("CREATE LOCAL INDEX I3 ON V (V1)");
    try {
        PhoenixRuntime.getTenantIdExpression(tsconn, "I3");
        fail();
    } catch (SQLFeatureNotSupportedException e) {
        // Expected
    }
}

