public void testVariousOperations() throws Exception {
    int numTenantGroups = 3;
    int numOpGroups = 5;
    int numRuns = 10;
    int numOperations = 10;
    PhoenixUtil pUtil = PhoenixUtil.create();
    Properties properties = PherfConstants.create().getProperties(PherfConstants.PHERF_PROPERTIES, false);
    DataModel model = readTestDataModel("/scenario/test_evt_gen1.xml");
    for (Scenario scenario : model.getScenarios()) {
        LOGGER.debug(String.format("Testing %s", scenario.getName()));
        LoadProfile loadProfile = scenario.getLoadProfile();
        assertEquals("tenant group size is not as expected: ", numTenantGroups, loadProfile.getTenantDistribution().size());
        assertEquals("operation group size is not as expected: ", numOpGroups, loadProfile.getOpDistribution().size());
        WeightedRandomLoadEventGenerator evtGen = new WeightedRandomLoadEventGenerator(pUtil, model, scenario, properties);
        TenantOperationFactory opFactory = evtGen.getOperationFactory();
        assertEquals("operation group size from the factory is not as expected: ", numOpGroups, opFactory.getOperations().size());
        for (int i = 0; i < numRuns; i++) {
            int ops = numOperations;
            loadProfile.setNumOperations(ops);
            while (ops-- > 0) {
                TenantOperationInfo info = evtGen.next();
                switch(TestOperationGroup.valueOf(info.getOperationGroupId())) {
                    case upsertOp:
                        assertTrue(opFactory.getOperationSupplier(info).getClass().isAssignableFrom(UpsertOperationSupplier.class));
                        break;
                    case queryOp1:
                    case queryOp2:
                        assertTrue(opFactory.getOperationSupplier(info).getClass().isAssignableFrom(QueryOperationSupplier.class));
                        break;
                    case idleOp:
                        assertTrue(opFactory.getOperationSupplier(info).getClass().isAssignableFrom(IdleTimeOperationSupplier.class));
                        break;
                    case udfOp:
                        assertTrue(opFactory.getOperationSupplier(info).getClass().isAssignableFrom(UserDefinedOperationSupplier.class));
                        break;
                    default:
                        Assert.fail();
                }
            }
        }
    }
}

